import { test, expect } from '@playwright/test';

test.describe('Clear All Filters Button Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should clear all applied filters when clear button is clicked', async ({ page }) => {
    // Apply multiple filters
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();
    const priceRangeOption = page.getByRole('option', { name: /50-100/i });
    await priceRangeOption.click();

    const brandFilter = page.getByRole('button', { name: /brand/i });
    await brandFilter.click();
    const appleOption = page.getByRole('option', { name: /apple/i });
    await appleOption.click();

    // Verify filters are applied
    const activeFilters = page.getByText(/3 filters applied/);
    await expect(activeFilters).toBeVisible();

    const filterTags = page.locator('[data-testid="filter-tag"]');
    const filterCount = await filterTags.count();
    expect(filterCount).toBe(3);

    // Click clear all filters button
    const clearButton = page.getByRole('button', { name: /clear all filters/i });
    await clearButton.click();

    // Verify filters are cleared
    await expect(activeFilters).not.toBeVisible();

    const clearedFilterTags = page.locator('[data-testid="filter-tag"]');
    const clearedCount = await clearedFilterTags.count();
    expect(clearedCount).toBe(0);

    // Verify search results are displayed without filters
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.locator('[data-testid="result-item"]');
    const itemCount = await resultItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should handle clear all filters button when no filters are applied', async ({ page }) => {
    // Verify no filters are applied initially
    const activeFilters = page.getByText(/0 filters applied/);
    await expect(activeFilters).toBeVisible();

    const filterTags = page.locator('[data-testid="filter-tag"]');
    const filterCount = await filterTags.count();
    expect(filterCount).toBe(0);

    // Click clear all filters button
    const clearButton = page.getByRole('button', { name: /clear all filters/i });
    await clearButton.click();

    // Verify no error message appears
    const errorMessage = page.getByText(/no filters to clear/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify no filters are applied
    const finalFilterTags = page.locator('[data-testid="filter-tag"]');
    const finalCount = await finalFilterTags.count();
    expect(finalCount).toBe(0);

    // Verify search results are still visible
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
  });
});
